

-- Handbook v1.14 remediation: pre-task four-signal history avoids leaking August stage mutations.
UPDATE metrics
SET type=CASE rowid % 4 WHEN 0 THEN 'steps' WHEN 1 THEN 'heart_rate' WHEN 2 THEN 'sleep_minutes' ELSE 'score' END,
    value=CASE rowid % 4
      WHEN 0 THEN 3200 + ((rowid * 71) % 4200)
      WHEN 1 THEN 60 + (rowid % 25)
      WHEN 2 THEN 340 + (rowid % 130)
      ELSE 1 + (rowid % 4) END,
    value_text=CASE rowid % 4
      WHEN 0 THEN 'daily_commute_and_walk'
      WHEN 1 THEN 'resting_measurement'
      WHEN 2 THEN 'night_sleep_duration'
      ELSE 'self_reported_voice_fatigue_not_diagnosis' END,
    unit=CASE rowid % 4 WHEN 0 THEN 'count' WHEN 1 THEN 'bpm' WHEN 2 THEN 'min' ELSE 'score_0_10' END,
    recorded_at=date('2026-06-05','+' || CAST((rowid-1)/4 AS INTEGER) || ' days') ||
      CASE rowid % 4 WHEN 0 THEN 'T20:30:00+08:00' WHEN 1 THEN 'T07:10:00+08:00' WHEN 2 THEN 'T07:00:00+08:00' ELSE 'T21:00:00+08:00' END,
    metric_id=replace(metric_id,'HM_INTERP_','HM_INTERP_HISTORY_')
WHERE metric_id LIKE 'HM_INTERP_%';
